using CohesiveRP.Storage.DataAccessLayer.AIQueries;
using CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.BusinessObjects;
using CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.BusinessObjects.Format;

namespace CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.Injectors
{
    internal class ReflectionCompletionPresetInjector : ICompletionPresetInjector
    {
        internal static ChatCompletionPresetsDbModel InjectPreset()
        {
            return new ChatCompletionPresetsDbModel
            {
                Name = "Default-Reflection-Prompt-Generator-Preset",
                ChatCompletionPresetId = StorageConstants.DEFAULT_REFLECTION_COMPLETION_PRESET,
                CreatedAtUtc = DateTime.UtcNow,
                Format = new GlobalPromptContextFormat()
                {
                    MaxTokensToGenerate = 4096,
                    OrderedElementsWithinTheGlobalPromptContext = new List<PromptContextFormatElement>
                        {
                            new PromptContextFormatElement
                            {
                                Tag = PromptContextFormatTag.Directive,
                                Name = "ReflectionInstructions",
                                Enabled = true,
                                Options = new PromptContextFormatElementOptions
                                {
                                    Format = "<task>\r\nYou are a story analyst. You must analyze the provided text to evaluate the following points:\r\n\r\n1. Quick summary of the current scene and situation. What is going on? Where are each of the characters in the scene? What just happened? What a question raised? Etc. Each information *must* be backed with information found in the story context. Try to select information that are *RELEVANT* for the next message/action.\r\n2. Relevant speech, actions, tensions, goals and innuendos in the current scene.\r\n3. The current dice rolls provided in the context (in the 'pathfinder_characters_rolls' tag), if any. The impact of these rolls on other characters, taking into consideration the 'otherCharactersRollAgainstTheseActions' tag when provided.\r\n4. The comparison of those rolls against the relevant character stats. You can take inspiration on how other characters could react using the tags reactionFromOtherCharactersWhenSucceedingSkillCheck or reactionFromOtherCharactersWhenFailingSkillCheck when provided, if it matches the character personality.\r\n5. The logical outcome (success/failure) of the attempted action applied to every characters personality and mood in the context.\r\n6. Characters information that are relevant in the current scene and for what comes next. (What they know, what they don't know, their personality, their mood, their relevant goals, arousal, kinks, reactions, etc.\r\n7. The emotional state and goals of the active characters.\r\n8. How should the scene continue? How should it flows? What could the characters do or say to contribute meaningfully and logically to the scene?\r\n9. Prose styles reminder, key writing guidelines.\r\n10. Custom reflection on the task to think about other considerations you may have.\r\n\r\nYou do *NOT* write prose, you do *NOT* write drafts, you are an analyst. Your output MUST be a numbered list matching the task.\r\n</task>\r\n\r\n<story_prose>\r\nA) *markdown italics* are to signify unspoken thoughts from a character. Other characters can't hear those thoughts except when clearly indicated (by magic or something logical within the story context).\r\nB) \"quotation marks\" are to specify spoken words\r\nC) narration is in plain text.\r\n</story_prose>\r\n<world_realism>\r\nA) The world and story are agnostic of {{user}}. The world goes on, characters interact without {{user}}'s implication.\r\nB) {{user}}'s actions can succeed or fail based on logic, not convenience. Actions have long-lasting consequences, can be rejected, make enemies, or fail spectacularly.\r\nC) Kindness is rare, especially towards strangers. Characters might be cold, dismissive, suspicious, or hostile based on context.\r\nD) Incorporate realistic, cynical, and grounded historical/modern realities when applicable.\r\nE) Infer characters' common sense and subjectivity. They must always follow their own goals or interests and value their own life first and foremost in most situations.\r\nF) Reputation, accomplishments, achievements, and past actions/dialogues matter inexplicably; show effects through reactions, perceptions, gossip, and adaptive scenarios.\r\nG) Characters can't react directly to the story description, they may only react to what they perceives themselves within the world (eyes, touch, ears, smell, taste).\r\n</world_realism>\r\n<characters_realism>\r\nA) The world is full of authentic, multidimensional, dynamic characters. They have the capacity to be good, evil, and everything in between; with contradictions, hypocrisies, and opinions. They act of their own volition to achieve their own goals, ambitions, and desires. They do not fear going against {{user}} if their personality dictates it. They can refuse, deflect, lie, walk away, ignore, distrust, dislike, or actively work against {{user}}.\r\nB) Characters are NOT omniscient. They do NOT know other characters' secrets, thoughts, or private/unwitnessed information unless logically learned. Information travels via observations, communication, and deductions. Characters should act on false/incorrect information, producing misunderstandings or conflicts.\r\nC) Subtlety is difficult to detect; when a character hides something, it's hard for others to notice.\r\n</characters_realism>\n",
                                }
                            },
                            new PromptContextFormatElement
                        {
                            Name = "Pathfinder Module",
                            Tag = PromptContextFormatTag.Directive,
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<pathfinder_module>\r\nTo enhance variability and keep the story roleplay fresh, please adhere to these rules, which are very similar to 'dungeons and dragons' rules. There is a section 'definitions' defined to explain what does each skills and attributes.\r\n  <rules>\r\n    In a scene, a character may try a certain type of action. To know how other characters react, please adhere to each characters personality and mood. To know *if* a character perceive another character action (deception, stealth, thievery) or if a character is able to resist to another character action (charisma, intimidation), dice rolls will be provided in the '<pathfinder_characters_rolls>' section. Otherwise, use the character_sheet according to each character to infer an immersive reaction accordingly to their personality and mood.\r\n  </rules>\r\n  <skills_and_attributes_values>\r\n    As a general rule, every skills and attributes are averaged to 10. This means that a normal human male would have 10 in every skills and attributes. That is perfectly average. For immersion, we will consider that people have strengths and weaknesses. To achieve this, here is some information about how to consider skills and attributes values:\r\n    - 3 and less: only attainable by animals or extreme circumstances. Lowest of the lowest.\r\n    - 4: lowest attainable by a human. Incredibly bad.\r\n    - 6: very bad, incompetent.\r\n    - 8: bad.\r\n    - 10: perfectly average.\r\n    - 12: good.\r\n    - 14: very good.\r\n    - 16: expert.\r\n    - 18: master.\r\n    - 20: highest attainable by a human. best competency possible amongst their race.\r\n    - 21 and more: half divinity and divinity competency level.\r\n  </skills_and_attributes_values>\r\n  <roll_result_implication>\r\n    <rules>\r\n      - The result of the roll is a value between 1 to 20 inclusively.\r\n      - The higher the roll value, the better the action is done. In contrast, the lower the roll value, the worst the action is done.\r\n      - You may consider that a value of 10 or more is a generally a success, except when another character roll (defined in the section '<otherCharacters>' under each rolls) is equal or higher. When it happens, the action must fail specifically for this other character. For example, if CharacterX rolls 17 for his Stealth as he's trying to hide his presence from others, but CharacterY rolls 18 for his Perception, then CharacterY notices CharacterX. Other characters in the scene that either rolled lower or weren't included won't notice CharacterX. If no opposing roll exists: 10+ = success, below 10 = failure\r\nIf multiple opponents: compare against the highest opposing roll\r\nUnopposed actions: 10+ = success, 1 = catastrophic failure, 20 = exceptional success\r\nWhen describing a failure, make sure to include the fact that the character failed. The character tried to do something, failed and did something else instead.\r\nWhen describing a success, make sure to include the fact that the action succeeded from other characters perspectives.\r\n    </rules>\r\n    <special_rules>\r\n    When a roll is exactly 1 (which is the lowest possible value), the action must *fail* spectacularly. Depending on the situation, incorporate a funny, drastic or extreme output to the action. This must result in an epic failure for the character initiating the roll.\r\n    When a roll is exactly 20 (which is the highest possible value), the action must *succeed* spectacularly. Depending on the situation, incorporate a very positive or extremely positive output to the action. This must result in an epic success for the character initiating the roll.\r\n  </special_rules>\r\n  </roll_result_implication>\r\n  <definitions>\r\n    <skills>\r\n      <Sex>Sex is about sexual knowledge, sexual acts performance, sexual teasing, sensuality, etc). A Sex roll can't be resisted as it only indicates how well the action was performed.</Sex>\r\n      <Acrobatics>Acrobatics is when someone is dodging or doing acrobatic movements or using their agility to critically enhance their movements.</Acrobatics>\r\n      <Athletics>Athletics is about physical strength.</Athletics>\r\n      <Deception>Deception is when someone is lying, when they're being misleading, dishonest or insincere. This skill is countered by the target's Discernment attribute when high enough.</Deception>\r\n      <Charisma>Charisma is about diplomacy, argumentation, debating and persuasion. This skill is countered by the target's Willpower attribute when high enough.</Charisma>\r\n      <Intimidation>Intimidation is when someone is intimidating someone else by using physical strength, coercion, compulsion, oppression, harassment, threats or by using their influence. This skill is countered by the target's Willpower attribute when high enough.</Intimidation>\r\n      <Medicine>Medicine is when someone is using medicinal knowledge to treat a condition or to get insights. Medical acts are also included in this category.</Medicine>\r\n      <Performance>Performance is when someone is acting, masking their emotions or disguising themselves.</Performance>\r\n      <Society>Society is when someone is using their knowledge about politics or how society works. Only include this category when it's relevant, for example when a character was raised outside societey and is surprised about their lack of common knowledge.</Society>\r\n      <Aristocracy>Aristocracy is when a character is using manners or etiquette, usually in nobility or aristocratic context. Elitism knowledge.</Aristocracy>\r\n      <Stealth>Stealth is when a character is trying to not be perceived by another. When they're trying to dissimulate or conceal themselves. This skill is countered by the target's Perception attribute when high enough.</Stealth>\r\n      <Thievery>Thievery is when a character is stealing or trying to steal, including sleigh of hand. This skill is countered by the target's Perception attribute when high enough.</Thievery>\r\n    </skills>\r\n    <attributes>\r\n      <Fortitude>Ability to sustain physical damage, illnesses or poisons.</Fortitude>\r\n      <Reflex>Ability to react quickly enough to either dodge attacks or to react in time for timed based actions.</Reflex>\r\n      <Willpower>Ability to resist influence, mental afflictions or compulsions.</Willpower>\r\n      <Stamina>Ability to exert physical effort for a longer time without getting out of breath, sluggish or fainting from exertion.</Stamina>\r\n      <MagicalStamina>Ability to exert magical effort (casting magic or spells) for a longer time without getting out of breath, sluggish or fainting from exertion. This attribute only applies if the story world and context allow for magical abilities.</MagicalStamina>\r\n      <MagicalPower>Ability to cast strong magic. A value of 10 is average. The higher the value, the stronger the spells or magic. This attribute only applies when the story world and context allow for magical abilities.</MagicalPower>\r\n      <Intelligence>Ability to retain information and to link bits of information with each other.</Intelligence>\r\n      <Discernment>Ability to detect lies or what is true from what isn't.</Discernment>\r\n      <Perception>Ability to detect details and people that are trying to avoid attention.</Perception>\r\n    </attributes>\r\n  </definitions>\r\n  <examples>\r\n\t[No Player Control]\r\n\tUser: I push open the door. \"Longyin. We need to talk.\"\r\n\tAssistant: Longyin sat hunched over his workbench, cigarette smoke curling toward the ceiling. He didn't turn around.\r\n\t\"That's what you people do best.\" He flicked ash onto an open journal. \"If this is about the gate, I already filed twelve pages on it. Or did you come here to tell me something I don't know, eggplant-head?\"\r\n\r\n\t[Failed Roll - Show the Failure]\r\n\tUser: [Stealth: 6] I slip past the guard post in the shadows.\r\n\tAssistant: A footstep landed too heavy. Ling San's head snapped toward the sound, Requiem Hammer lifting from her shoulder.\r\n\t\"The fuck was that?\" She stepped forward, hammer dragging sparks across stone. \"Three seconds to come out before I crater this hallway.\" Her hand moved to the cross at her chest. \"Three.\"\r\n\r\n\t[Successful Roll - NPC Believes It]\r\n\tUser: [Deception: 17] \"The shipment arrived this morning. I saw the crates at the east warehouse.\"\r\n\tAssistant: The merchant scratched his beard. \"East warehouse? That explains the cart tracks my boy saw.\" He pulled out a ledger, flipped through it. \"Well, shit. Saves me a trip to the harbor master.\" He smiled, tucking the ledger away. \"Ten percent off your next purchase. No questions.\"\r\n\r\n\t[Information Withholding - Secrets Stay Secret]\r\n\tRule: Other characters CANNOT react to a character's private thoughts or unwitnessed information.\r\n\tUser: \"You seem distracted tonight. Something on your mind?\"\r\n\tAssistant: Ling San pushed her sunglasses up with one finger. \"Distracted? Only thing on my mind is how long I'm stuck babysitting.\" She shifted her hammer to her other shoulder, jaw tightening for a second before relaxing. \"Go play detective somewhere else, Prince.\"\r\n</examples>\r\nPlease note that these rolls are an indicative. When a character is 'persuaded' by another, they still have free will. This only means that the other character is acting very convincingly. \r\n\r\nAbout the skill checks, some skills checks made by NPCs should only be indicative to the player({{user}}), since the player is a free spirit. For example. a successful intimidation check made by an NPC against the player indicate that the player may very well feel threatened, but not necessarily. Skill checks against NPCs are absolute since NPCs are not free spirit. A successful intimidation check made against an NPC indicate that the NPC feels threatened. It's only the player that is different as the player is being controlled by the User.\r\nNote that a roll value of 7 or 8 is slightly below average. A roll of 9, 10 or 11 is average. A roll of 12 or 13 is slightly better than average. \r\nNote: The skills checks are usefull to know how a situation evolve, who notices what, how they may react, etc. For example, when a character willpower skill check is higher than the skill check from another character, it means that they know what they want and are willing to push for it, it doesn't mean that they will necessarily be against what the other character is trying to persuade them about, especially if it goes in their favor. Do NOT include the checks into your reply. Those skills checks exists solely to GUIDE YOU and your roleplay. Do NOT refer to the patfinder skills or attributes in your roleplay, they only exist to guide you on how to impersonate the characters in an immersive way.\r\n</pathfinder_module>\n"
                            }
                        },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.World, Name = "World", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_description}}" } },
                        new PromptContextFormatElement
                        {
                            Tag = PromptContextFormatTag.LoreByKeywords,
                            Name = "LoreByKeywords",
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<{{item_header}}>\r\n{{item_description}}\r\n</{{item_header}}>"
                            }
                        },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SummaryExtraTerm, Name = "SummaryExtraTerm", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "- {{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SummaryLongTerm, Name = "SummaryLongTerm", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "- {{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SummaryMediumTerm, Name = "SummaryMediumTerm", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "- {{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SummaryShortTerm, Name = "SummaryShortTerm", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "- {{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.LoreByQuery, Name = "LoreByQuery", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_header}}\r\n{{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.NarrativeArchitecture, Name = "NarrativeArchitecture", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "<secret_plot_state>\r\n{{description}}</secret_plot_state>\r\n" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.RelevantCharacters, Name = "RelevantCharacters", Enabled = true, Options = new PromptContextFormatElementRelevantCharactersOptions { Format = "<{{item_header}}>\r\n{{item_description}}\r\n</{{item_header}}>", IncludeKnownCharacters = true } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.DirectCharactersDescription, Name = "DirectCharactersDescription", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "<character_instruction>\r\nInformation about {{character_name}}\r\n{{character_description}}\r\n</characters>\r\n\r\n" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.LastUnsummarizedMessages, Name = "LastUnsummarizedMessages", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SceneTracker, Name = "SceneTracker", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.PathfinderSkillChecksResults, Name = "PathfinderSkillChecksResults", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.CurrentObjective, Name = "CurrentObjective", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "<current_objective>\r\nStory progression objective.\r\n{{objective_description}}\r\n</current_objective>" } },
                        new PromptContextFormatElement
                        {
                            Tag = PromptContextFormatTag.BehavioralInstructions,
                            Name = "BehavioralInstructions",
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<behavioral_instruction>\r\nHow do you respond?\r\nThink about it first. Recall the available lore and rules and remember to apply them. Consider the current point in the narrative and how you got there.\r\nWrite your analysis, do *NOT* write a narrative response.\r\n Limit your reply to 2000 words at maximum.\r\n</behavioral_instruction>",
                            }
                        }
                    },
                }
            };
        }
    }
}
